import numpy as np


def compare_methods(grad, hess, x0, tol=1e-8, max_iter=100000):
    scalar = np.ndim(x0) == 0
    x0 = np.atleast_1d(np.asarray(x0, dtype=float))

    def G(x):
        return np.atleast_1d(np.asarray(grad(x[0] if scalar else x), dtype=float))

    def H(x):
        return np.atleast_2d(np.asarray(hess(x[0] if scalar else x), dtype=float))

    ev = np.linalg.eigvalsh(H(x0))
    s = 2 / (ev.min() + ev.max())
    x, a = x0.copy(), 0
    while np.linalg.norm(G(x)) > tol and a < max_iter:
        x = x - s * G(x)
        a += 1
    x, b = x0.copy(), 0
    while np.linalg.norm(G(x)) > tol and b < max_iter:
        x = x - np.linalg.solve(H(x), G(x))
        b += 1
    return a, b
